// For a nonnull battle scene and absent g_BattleSummonOdinGLoadedResTable resource, initializes a default-duration
// record using SUMMON/odin1 path, creates resource category 0xC through g_BattleSummonOdinGResourceDef with the
// scene's model table bank, and registers g_BattleSummonOdinGSoundGroupPointers sound groups.
// FUNCTION: FF7 0x004a0a40
void __cdecl BattleFx_SummonLoadResOdinGungnir(void)
{
    GfxModelTableBank *stage;
    GfxResourceRequest requestSlot;
    int kind;
    char pathText[200];
    GfxResourceRequest *pRequest;
    int resourceTable;

    if (g_pBattle3dScene != 0 && g_BattleSummonOdinGLoadedResTable == 0) {
        kind = 0xC;
        resourceTable = (int)&g_BattleSummonOdinGResourceDef;
        stage = (GfxModelTableBank *)g_pBattle3dScene->modelTableBank;
        pRequest = &requestSlot;
        Gfx_InitResourceRequest(pRequest);
        ((BattleFxDiamondCardResource *)pRequest)->groupTag = 0;
        // STRING: FF7 0x00803e38
        ((BattleFxDiamondCardResource *)pRequest)->resourcePath = (int)BattleFx_BuildResourcePath("SUMMON/odin1", pathText);
        Gfx_LoadModelTableIfAbsent(kind, resourceTable, pRequest, &g_BattleSummonOdinGLoadedResTable, stage);
        SfxRegisterSoundGroups((struct SoundGroup **)&g_BattleSummonOdinGSoundGroupPointers);
    }
}

// Clears g_BattleSummonOdinGInitialAngles and three 30-byte matrices, sets the spear matrix's
// diagonal (g_BattleSummonOdinGParamB190[0], g_BattleSummonOdinGParamB198 and
// g_BattleSummonOdinGParamB1A0.m22) to 0x1000/-0x1000/-0x1000, calls BattleFx_SummonBeginOdinGungnir
// with both arguments, and returns zero.
// FUNCTION: FF7 0x004a0ae1
int __cdecl BattleFx_SummonEnterOdinGungnir(int targetMask, int actorIdx)
{
    g_BattleSummonOdinGInitialAngles.angleZ = 0;
    g_BattleSummonOdinGInitialAngles.angleY = g_BattleSummonOdinGInitialAngles.angleZ;
    g_BattleSummonOdinGInitialAngles.angleX = g_BattleSummonOdinGInitialAngles.angleY;
    memset(&g_BattleSummonOdinGMatrixD530, 0, 0x1E);
    memset(&g_BattleSummonOdinGMatrixB168, 0, 0x1E);
    memset(g_BattleSummonOdinGParamB190, 0, 0x1E);
    g_BattleSummonOdinGParamB190[0] = 0x1000;
    g_BattleSummonOdinGParamB1A0.m22 = 0xF000;
    g_BattleSummonOdinGParamB198 = g_BattleSummonOdinGParamB1A0.m22;
    BattleFx_SummonBeginOdinGungnir(targetMask, actorIdx);
    return 0;
}

// Refreshes render-state chain and loads Odin Gungnir resources. Selects the first of ten actorMask
// actor bits into g_BattleSummonOdinGTargetActorIdx, retaining prior selection if none; obtains its
// target-bone position into position; positionZ, which the code compares with actorIndex's Z, is a
// separate local the call never writes. If it is greater writes it minus 3400 to matrix Z;
// otherwise sets angle 0x800 and writes it plus 3400. Writes position's low short as matrix X and
// builds rotation, preserving conditional angle retention. Calls
// BattleFx_SummonOdinGungnirComputeVertexDeltas for two distinct mesh/table/output groups, clears
// g_BattleSummonOdinGStateA8 and visits parts of nonnull resource fields zero/one with separate
// callbacks. Schedules BattleFx_SummonOdinGungnirTimelineTask with eight copied output bytes,
// consumes rand bit 0x100 to choose g_BattleSummonOdinGCameraScript1 or 2 and sets stage-hide flag
// eight.
// FUNCTION: FF7 0x004a0b6d
void __cdecl BattleFx_SummonBeginOdinGungnir(int targetMask, int casterIdx)
{
    SVECTOR position;
    int slot;
    int slotPtr;
    int partEntry;

    g_BattleOverlayDrawListHead = Gfx_GetPsxPacketScratchPtr();
    BattleFx_SummonLoadResOdinGungnir();
    for (slot = 0; slot < 0xA; slot++) {
        if ((targetMask & 1 << slot) != 0) {
            g_BattleSummonOdinGTargetActorIdx.actorIdx = slot;
            break;
        }
    }
    Battle_GetBoneWorldPos(g_BattleSummonOdinGTargetActorIdx.actorIdx, g_BattleActorRecords[g_BattleSummonOdinGTargetActorIdx.actorIdx].targetBone, &position.vx);
    if (position.vz > g_BattleActorRecords[casterIdx].posZ) {
        g_BattleSummonOdinGMatrixD530.t[2] = position.vz - 0xD48;
    } else {
        g_BattleSummonOdinGInitialAngles.angleY = 0x800;
        g_BattleSummonOdinGMatrixD530.t[2] = position.vz + 0xD48;
    }
    g_BattleSummonOdinGMatrixD530.t[0] = position.vx;
    RotMatrix((SVECTOR *)&g_BattleSummonOdinGInitialAngles, &g_BattleSummonOdinGMatrixD530);
    BattleFx_SummonOdinGungnirComputeVertexDeltas(&g_BattleSummonOdinGVertexDeltasParam1, (struct Vec3sPacked *)g_BattleSummonOdinGVertexDeltasTable1, (struct Vec3sPacked *)&g_BattleSummonOdinGTaskSlot71A8);
    BattleFx_SummonOdinGungnirComputeVertexDeltas(&g_BattleSummonOdinGVertexDeltasParam2, (struct Vec3sPacked *)g_BattleSummonOdinGVertexDeltasTable2, (struct Vec3sPacked *)&g_BattleSummonOdinGTaskSlotB1D0);
    g_BattleSummonOdinGStateA8 = 0;
    partEntry = Gfx_ModelTableGetRenderObject(0, g_BattleSummonOdinGLoadedResTable);
    if (partEntry != 0) {
        Gfx_ForEachPolygonSetPart((DxGroupPartCallback)BattleFx_SummonOdinGungnirBlendPolygonSetVerticesResource0, *(int *)((char *)partEntry + 4));
    }
    partEntry = Gfx_ModelTableGetRenderObject(1, g_BattleSummonOdinGLoadedResTable);
    if (partEntry != 0) {
        Gfx_ForEachPolygonSetPart((DxGroupPartCallback)BattleFx_SummonOdinGungnirBlendPolygonSetVerticesResource1, *(int *)((char *)partEntry + 4));
    }
    slotPtr = (int)BATTLE_NEW_TASK_SLOT(BattleFx_SummonOdinGungnirTimelineTask);
    *(Int64Pair *)((char *)slotPtr + 4) = *(Int64Pair *)(&position);
    if ((rand() & 0x100) != 0) {
        BattleFx_OdinGungnirSpawnCameraScript(&g_BattleSummonOdinGCameraScript1, (int)&g_BattleSummonOdinGMatrixD530, casterIdx);
    } else {
        BattleFx_OdinGungnirSpawnCameraScript(&g_BattleSummonOdinGCameraScript2, (int)&g_BattleSummonOdinGMatrixD530, casterIdx);
    }
    g_BattleStageHideFlags |= 8;
}

