    ofsRef = (Vec3sPacked *)(vertexIndex * 8 + (char *)&g_BattleSummonOdinGTaskSlot71A8);
    factor = 0x1000 - g_BattleSummonOdinGStateA8;
    blendX = basePointer->vx + (ofsRef->vx * factor >> 0xC);
