// Uses the initial sourceBlock dword divided by eight as a record count, subtracts three offsetTable words from
// three words of each sourceBlock+4 eight-byte record into dst, and advances all record pointers by
// eight; padding words are untouched.
// FUNCTION: FF7 0x004a0e75
void __cdecl BattleFx_SummonOdinGungnirComputeVertexDeltas(void *sourceBlock, Vec3sPacked *offsetTable, Vec3sPacked *dst)
{
    Vec3sPacked *sourceRecord;
    int count;
    int index;

    count = *(int *)sourceBlock / 8;
    sourceRecord = (Vec3sPacked *)((int)sourceBlock + 4);
    for (index = 0; index < count; index++) {
        dst->vx = sourceRecord->vx - offsetTable->vx;
        dst->vy = sourceRecord->vy - offsetTable->vy;
        dst->vz = sourceRecord->vz - offsetTable->vz;
        sourceRecord = (Vec3sPacked *)((char *)sourceRecord + 8);
        offsetTable = (Vec3sPacked *)((char *)offsetTable + 8);
        dst = (Vec3sPacked *)((char *)dst + 8);
    }
}

