// Same token reader as BattleFx_NeoBahamutReadCameraScriptOperand with the pool at g_BattleSummonOdinGTargetActorIdx + 6: reads a short from the cursor
// at cursor, advances it by 2, and resolves a negative token as
// `((short *)((char *)&g_BattleSummonOdinGTargetActorIdx + 6))[-token]`.
// FUNCTION: FF7 0x004a1e83
short __cdecl BattleFx_OdinGungnirReadCameraScriptOperand(int *cursor)
{
    int token;

    token = *(short *)*cursor;
    *cursor += 2;
    if (token < 0) {
        token = g_BattleSummonOdinGTargetActorIdx.operandPool[-token];
    }
    return (short)token;
}

// Fixed-point easing helper: phase is a 0..0x1000 phase, packed packs a signed repeat count in bits
// 8+ and a blend weight in the low byte. Applies SinFixed(phase / 4) count times (mirrored through
// 0x1000 - phase when the count is negative) and returns the result blended with the original phase
// by weight/256. Pure function; touches no globals.
// FUNCTION: FF7 0x004a1ebd
int __cdecl BattleFx_OdinGungnirApplyCameraEasing(int phase, int packed)
{
    int i;
    int iterCount;
    int orig;

    orig = phase;
    iterCount = packed >> 8;
    if (iterCount > 0) {
        for (i = 0; i < iterCount; i++) {
            phase = SinFixed(phase / 4);
        }
    } else {
        phase = 0x1000 - phase;
        for (i = 0; i < -iterCount; i++) {
            phase = SinFixed(phase / 4);
        }
        phase = 0x1000 - phase;
    }
    iterCount = packed & 0xFF;
    phase = (phase * iterCount + orig * (0x100 - iterCount)) >> 8;
    return phase;
}

